(function(){
var D=window.__I18N||{};var TH=/[฀-๿]/;
var keys=Object.keys(D).filter(function(k){return k.length>=2}).sort(function(a,b){return b.length-a.length});
var RX=new RegExp(keys.map(function(k){return k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}).join('|'),'g');
function norm(s){return s.replace(/\s+/g,' ').trim()}
function tr(s){
  if(!TH.test(s))return null;
  var k=norm(s);if(D[k]!=null){var m=s.match(/^\s*/)[0],e=s.match(/\s*$/)[0];if(/^[,.;:]/.test(D[k]))m='';return m+D[k]+e}
  var o=s.replace(RX,function(x){return '\u0001'+D[x]+'\u0001'});
  if(o===s)return null;
  var m2=s.match(/^\s*/)[0],e2=s.match(/\s*$/)[0];
  o=o.replace(/\u0001+/g,' ').replace(/ {2,}/g,' ').replace(/ ([,.:;)!?])/g,'$1').replace(/\( /g,'(').trim();
  return m2+o+e2;
}
var params=new URLSearchParams(location.search);var lang=params.get('lang');
try{if(lang)localStorage.setItem('lang',lang);else lang=localStorage.getItem('lang')}catch(e){}
if(lang!=='en')lang='th';
var T=new WeakMap();var ATTR=['alt','title','aria-label','placeholder'];var busy=false;
function doText(n){
  var cur=n.nodeValue,rec=T.get(n);
  if(!rec||cur!==rec.w){rec={o:cur,w:cur};T.set(n,rec)}
  var want=lang==='en'?(tr(rec.o)||rec.o):rec.o;
  if(cur!==want){n.nodeValue=want}rec.w=want;
}
function doEl(el){
  var rec=T.get(el);if(!rec){rec={};T.set(el,rec)}
  for(var i=0;i<ATTR.length;i++){var a=ATTR[i];if(!el.hasAttribute(a))continue;var cur=el.getAttribute(a),r=rec[a];
    if(!r||cur!==r.w){r={o:cur,w:cur};rec[a]=r}
    var want=lang==='en'?(tr(r.o)||r.o):r.o;if(cur!==want)el.setAttribute(a,want);r.w=want}
}
function walk(root){
  if(root.nodeType===3){doText(root);return}
  if(root.nodeType!==1)return;var tg=root.tagName;if(tg==='SCRIPT'||tg==='STYLE'||tg==='TEMPLATE')return;
  if(root.id==='langsw')return;
  doEl(root);
  var w=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT,{acceptNode:function(n){
    if(n.nodeType===1){var t=n.tagName;if(t==='SCRIPT'||t==='STYLE'||t==='TEMPLATE'||n.id==='langsw')return 2;return 1}return 1}});
  var n;while(n=w.nextNode()){if(n.nodeType===3)doText(n);else doEl(n)}
}
function apply(root){busy=true;try{walk(root||document.body)}finally{busy=false}
  document.documentElement.lang=lang;var b=document.getElementById('langsw');
  if(b){var s=b.querySelectorAll('span');s[0].className=lang==='th'?'on':'';s[1].className=lang==='en'?'on':'';b.setAttribute('aria-label',lang==='en'?'Switch language to Thai':'เปลี่ยนภาษาเป็นอังกฤษ')}}
var pend=[],sch=false;
var mo=new MutationObserver(function(ms){if(busy)return;
  for(var i=0;i<ms.length;i++){var m=ms[i];if(m.type==='childList'){for(var j=0;j<m.addedNodes.length;j++)pend.push(m.addedNodes[j])}else pend.push(m.target)}
  if(!sch){sch=true;(window.queueMicrotask||setTimeout)(function(){sch=false;var p=pend;pend=[];busy=true;try{p.forEach(function(n){if(n.isConnected)walk(n)})}finally{busy=false}})}
});
function setLang(l){lang=l;try{localStorage.setItem('lang',l)}catch(e){}
  try{var u=new URL(location.href);if(l==='en')u.searchParams.set('lang','en');else u.searchParams.delete('lang');history.replaceState(history.state,'',u)}catch(e){}
  apply();}
window.__setLang=setLang;
function ui(){
  var st=document.createElement('style');st.textContent='#langsw{position:fixed;z-index:60;top:18px;right:18px;display:flex;gap:2px;padding:4px;border:0;border-radius:12px;background:#FFFFFF;box-shadow:0 6px 20px rgba(28,36,64,.16);cursor:pointer;font:700 12.5px/1 system-ui,-apple-system,"Segoe UI",sans-serif;letter-spacing:.04em;transition:translate .2s,box-shadow .2s}#langsw:hover{translate:0 -2px;box-shadow:0 0 0 3px #DFFF1A,0 10px 20px rgba(28,36,64,.18)}#langsw span{display:inline-flex;align-items:center;justify-content:center;min-width:34px;height:30px;border-radius:9px;color:#5A6380}#langsw span.on{background:#1C2440;color:#FFFFFF}#langsw:focus-visible{outline:3px solid #2457E6;outline-offset:2px}@media (max-width:1279px){#langsw{top:auto;bottom:18px;right:auto;left:16px}}@media print{#langsw{display:none}}';
  document.head.appendChild(st);
  var b=document.createElement('button');b.id='langsw';b.type='button';b.innerHTML='<span>TH</span><span>EN</span>';
  b.addEventListener('click',function(){setLang(lang==='en'?'th':'en')});document.body.appendChild(b);
}
function start(){ui();apply();mo.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:ATTR})}
if(document.body)start();else document.addEventListener('DOMContentLoaded',start);
})();
